samples/apps/n_reinas.aym.source:
qallta
yatiya jakhüwi N = 8;
yatiya t'aqa col = [];
yatiya t'aqa diag_prin = [];
yatiya t'aqa diag_sec = [];
yatiya jakhüwi soluciones = 0;

lurawi reinicia_marcadores() {
  col = [];
  diag_prin = [];
  diag_sec = [];

  kuti(yatiya jakhüwi i = 0; i < N; i = i + 1) {
    push(col, 0);
  }

  kuti(yatiya jakhüwi i = 0; i < (2 * N - 1); i = i + 1) {
    push(diag_prin, 0);
    push(diag_sec, 0);
  }
  kuttaya;
}

lurawi idx_diag_prin(jakhüwi fila, jakhüwi columna): jakhüwi {
  kuttaya fila - columna + N - 1;
}

lurawi idx_diag_sec(jakhüwi fila, jakhüwi columna): jakhüwi {
  kuttaya fila + columna;
}

lurawi disponible(jakhüwi fila, jakhüwi columna): chiqa {
  ukaxa(col[columna] == 1) { kuttaya k'ari; }
  ukaxa(diag_prin[idx_diag_prin(fila, columna)] == 1) { kuttaya k'ari; }
  ukaxa(diag_sec[idx_diag_sec(fila, columna)] == 1) { kuttaya k'ari; }
  kuttaya chiqa;
}

lurawi marca(jakhüwi fila, jakhüwi columna, jakhüwi valor) {
  col[columna] = valor;
  diag_prin[idx_diag_prin(fila, columna)] = valor;
  diag_sec[idx_diag_sec(fila, columna)] = valor;
  kuttaya;
}

lurawi busca(jakhüwi fila) {
  ukaxa(fila == N) {
    soluciones = soluciones + 1;
    kuttaya;
  }

  kuti(yatiya jakhüwi c = 0; c < N; c = c + 1) {
    ukaxa(! disponible(fila, c)) { sarantaña; }
    marca(fila, c, 1);
    busca(fila + 1);
    marca(fila, c, 0);
  }
  kuttaya;
}

reinicia_marcadores();
busca(0);

qillqa("n =", N);
qillqa("soluciones =", soluciones);
afirma(soluciones == 92, "n-reinas N=8 deberia tener 92 soluciones");
qillqa("n_reinas OK");
tukuya

samples/apps/banca_excepciones.aym.source:
qallta
kasta QullqiUta {
  yatiya aru sutipa;
  yatiya jakhüwi saldo;

  qallta(aru n, jakhüwi q) {
    aka.sutipa = n;
    aka.saldo = q;
  }

  lurawi uchaña(jakhüwi q) {
    ukaxa(q <= 0) {
      pantja("MONTO", "monto debe ser mayor que cero");
    }
    aka.saldo = aka.saldo + q;
    kuttaya;
  }

  lurawi apsuña(jakhüwi q) {
    ukaxa(q <= 0) {
      pantja("MONTO", "monto debe ser mayor que cero");
    }
    ukaxa(q > aka.saldo) {
      pantja("SALDO", "saldo insuficiente en " + aka.sutipa);
    }
    aka.saldo = aka.saldo - q;
    kuttaya;
  }

  lurawi resumen(): aru {
    kuttaya aka.sutipa + ":" + aru(aka.saldo);
  }
}

lurawi transferi(QullqiUta origen, QullqiUta destino, jakhüwi q) {
  origen.apsuña(q);
  destino.uchaña(q);
  kuttaya;
}

yatiya QullqiUta ana = machaqa QullqiUta("Ana", 500);
yatiya QullqiUta luis = machaqa QullqiUta("Luis", 250);

yant'aña {
  transferi(ana, luis, 120);
  transferi(luis, ana, 50);
  transferi(luis, ana, 1000);
} katjaña("SALDO", e) {
  qillqa("error capturado", e.suti, e.aru);
}

qillqa(ana.resumen());
qillqa(luis.resumen());
afirma(ana.saldo == 430, "saldo Ana inesperado");
afirma(luis.saldo == 320, "saldo Luis inesperado");
qillqa("banca_excepciones OK");
tukuya

