tukuya

samples/games/console/tetris.aym.source:
// Tetris completo de consola (version compacta) para juego por sesion.
// Controles: A/D izquierda/derecha, W rotar, S bajar, Q salir.

yatiya jakhüwi ANCHO = 10;
yatiya jakhüwi ALTO = 20;
yatiya jakhüwi tablero = 0;

yatiya jakhüwi px = 4;
yatiya jakhüwi py = 0;
yatiya jakhüwi tipo = 0;
yatiya jakhüwi rot = 0;
yatiya jakhüwi colorp = 1;

yatiya jakhüwi score = 0;
yatiya jakhüwi record = 0;
yatiya chiqa fin = k'ari;
yatiya jakhüwi prox_caida = 0;
yatiya chiqa giro_listo = chiqa;

lurawi nuevo_tablero(): jakhüwi {
  yatiya jakhüwi tb = array(ALTO);
  kuti(yatiya jakhüwi y = 0; y < ALTO; y = y + 1) {
    yatiya jakhüwi fila = array(ANCHO);
    kuti(yatiya jakhüwi x = 0; x < ANCHO; x = x + 1) {
      array_set(fila, x, 0);
    }
    array_set(tb, y, fila);
  }
  kuttaya tb;
}

lurawi celda_get(jakhüwi x, jakhüwi y): jakhüwi {
  yatiya jakhüwi fila = array_get(tablero, y);
  kuttaya array_get(fila, x);
}

lurawi celda_set(jakhüwi x, jakhüwi y, jakhüwi v) {
  yatiya jakhüwi fila = array_get(tablero, y);
  array_set(fila, x, v);
  kuttaya;
}

// type: 0=I,1=O,2=T,3=L,4=S
lurawi p_dx(jakhüwi t, jakhüwi r, jakhüwi i): jakhüwi {
  ukaxa(t == 0) {
    ukaxa(r == 0 || r == 2) { kuttaya i; }
    kuttaya 1;
  }
  ukaxa(t == 1) {
    ukaxa(i == 0 || i == 2) { kuttaya 0; }
    kuttaya 1;
  }
  ukaxa(t == 2) {
    ukaxa(r == 0) { ukaxa(i == 0) { kuttaya 1; } ukaxa(i == 1) { kuttaya 0; } ukaxa(i == 2) { kuttaya 1; } kuttaya 2; }
    ukaxa(r == 1) { ukaxa(i == 0) { kuttaya 1; } ukaxa(i == 1) { kuttaya 1; } ukaxa(i == 2) { kuttaya 1; } kuttaya 2; }
    ukaxa(r == 2) { ukaxa(i == 0) { kuttaya 0; } ukaxa(i == 1) { kuttaya 1; } ukaxa(i == 2) { kuttaya 2; } kuttaya 1; }
    ukaxa(i == 0) { kuttaya 0; } ukaxa(i == 1) { kuttaya 1; } ukaxa(i == 2) { kuttaya 1; } kuttaya 1;
  }
  ukaxa(t == 3) {
    ukaxa(r == 0) { ukaxa(i == 0) { kuttaya 0; } ukaxa(i == 1) { kuttaya 0; } ukaxa(i == 2) { kuttaya 1; } kuttaya 2; }
    ukaxa(r == 1) { ukaxa(i == 0) { kuttaya 1; } ukaxa(i == 1) { kuttaya 2; } ukaxa(i == 2) { kuttaya 1; } kuttaya 1; }
    ukaxa(r == 2) { ukaxa(i == 0) { kuttaya 0; } ukaxa(i == 1) { kuttaya 1; } ukaxa(i == 2) { kuttaya 2; } kuttaya 2; }
    ukaxa(i == 0) { kuttaya 1; } ukaxa(i == 1) { kuttaya 1; } ukaxa(i == 2) { kuttaya 0; } kuttaya 1;
  }
  // S
  ukaxa(r == 0 || r == 2) {
    ukaxa(i == 0) { kuttaya 1; } ukaxa(i == 1) { kuttaya 2; } ukaxa(i == 2) { kuttaya 0; } kuttaya 1;
  }
  ukaxa(i == 0) { kuttaya 1; } ukaxa(i == 1) { kuttaya 1; } ukaxa(i == 2) { kuttaya 2; } kuttaya 2;
}

lurawi p_dy(jakhüwi t, jakhüwi r, jakhüwi i): jakhüwi {
  ukaxa(t == 0) {
    ukaxa(r == 0 || r == 2) { kuttaya 1; }
    kuttaya i;
  }
  ukaxa(t == 1) {
    ukaxa(i < 2) { kuttaya 0; } kuttaya 1;
  }
  ukaxa(t == 2) {
    ukaxa(r == 0) { ukaxa(i == 0) { kuttaya 0; } ukaxa(i == 1) { kuttaya 1; } ukaxa(i == 2) { kuttaya 1; } kuttaya 1; }
    ukaxa(r == 1) { ukaxa(i == 0) { kuttaya 0; } ukaxa(i == 1) { kuttaya 1; } ukaxa(i == 2) { kuttaya 2; } kuttaya 1; }
    ukaxa(r == 2) { ukaxa(i == 0) { kuttaya 1; } ukaxa(i == 1) { kuttaya 1; } ukaxa(i == 2) { kuttaya 1; } kuttaya 2; }
    ukaxa(i == 0) { kuttaya 1; } ukaxa(i == 1) { kuttaya 0; } ukaxa(i == 2) { kuttaya 1; } kuttaya 2;
  }
  ukaxa(t == 3) {
    ukaxa(r == 0) { ukaxa(i == 0) { kuttaya 0; } ukaxa(i == 1) { kuttaya 1; } ukaxa(i == 2) { kuttaya 1; } kuttaya 1; }
    ukaxa(r == 1) { ukaxa(i == 0) { kuttaya 0; } ukaxa(i == 1) { kuttaya 0; } ukaxa(i == 2) { kuttaya 1; } kuttaya 2; }
    ukaxa(r == 2) { ukaxa(i == 0) { kuttaya 1; } ukaxa(i == 1) { kuttaya 1; } ukaxa(i == 2) { kuttaya 1; } kuttaya 2; }
    ukaxa(i == 0) { kuttaya 0; } ukaxa(i == 1) { kuttaya 1; } ukaxa(i == 2) { kuttaya 2; } kuttaya 2;
  }
  // S
  ukaxa(r == 0 || r == 2) {
    ukaxa(i == 0) { kuttaya 0; } ukaxa(i == 1) { kuttaya 0; } ukaxa(i == 2) { kuttaya 1; } kuttaya 1;
  }
  ukaxa(i == 0) { kuttaya 0; } ukaxa(i == 1) { kuttaya 1; } ukaxa(i == 2) { kuttaya 1; } kuttaya 2;
}

lurawi colisiona(jakhüwi nx, jakhüwi ny, jakhüwi nr): chiqa {
  kuti(yatiya jakhüwi i = 0; i < 4; i = i + 1) {
    yatiya jakhüwi x = nx + p_dx(tipo, nr, i);
    yatiya jakhüwi y = ny + p_dy(tipo, nr, i);
    ukaxa(x < 0 || x >= ANCHO || y < 0 || y >= ALTO) { kuttaya chiqa; }
    ukaxa(celda_get(x, y) != 0) { kuttaya chiqa; }
  }
  kuttaya k'ari;
}

lurawi celda_pieza(jakhüwi x, jakhüwi y): chiqa {
  kuti(yatiya jakhüwi i = 0; i < 4; i = i + 1) {
    ukaxa(x == px + p_dx(tipo, rot, i) && y == py + p_dy(tipo, rot, i)) { kuttaya chiqa; }
  }
  kuttaya k'ari;
}

lurawi fijar_pieza() {
  kuti(yatiya jakhüwi i = 0; i < 4; i = i + 1) {
    celda_set(px + p_dx(tipo, rot, i), py + p_dy(tipo, rot, i), colorp);
  }
  kuttaya;
}

lurawi limpiar_lineas(): jakhüwi {
  yatiya jakhüwi pts = 0;
  kuti(yatiya jakhüwi y = ALTO - 1; y >= 0; y = y - 1) {
    yatiya chiqa llena = chiqa;
    kuti(yatiya jakhüwi x = 0; x < ANCHO; x = x + 1) {
      ukaxa(celda_get(x, y) == 0) { llena = k'ari; }
    }
    ukaxa(llena) {
      pts = pts + 100;
      kuti(yatiya jakhüwi yy = y; yy > 0; yy = yy - 1) {
        kuti(yatiya jakhüwi x2 = 0; x2 < ANCHO; x2 = x2 + 1) {
          celda_set(x2, yy, celda_get(x2, yy - 1));
        }
      }
      kuti(yatiya jakhüwi x3 = 0; x3 < ANCHO; x3 = x3 + 1) { celda_set(x3, 0, 0); }
      y = y + 1;
    }
  }
  kuttaya pts;
}

lurawi nueva_pieza() {
  tipo = random(5);
  rot = random(4);
  px = 3;
  py = 0;
  colorp = 1 + random(6);
  ukaxa(colisiona(px, py, rot)) { fin = chiqa; }
  kuttaya;
}

lurawi reinicia_partida() {
  tablero = nuevo_tablero();
  px = 4;
  py = 0;
  tipo = 0;
  rot = 0;
  colorp = 1;
  score = 0;
  fin = k'ari;
  giro_listo = chiqa;
  nueva_pieza();
  prox_caida = tiempo_ms() + 420;
  pantalla_limpia();
  kuttaya;
}

lurawi dibuja() {
  cursor_mover(1, 1);
  qillqa("AymaraLang Tetris Full");
  qillqa("+--------------------+");
  kuti(yatiya jakhüwi y = 0; y < ALTO; y = y + 1) {
    write("|");
    kuti(yatiya jakhüwi x = 0; x < ANCHO; x = x + 1) {
      yatiya jakhüwi v = celda_get(x, y);
      ukaxa(celda_pieza(x, y)) { v = colorp; }
      ukaxa(v == 0) {
        write("  ");
      } maysatxa {
        color(v, 0);
        write("[]");
        color_restablecer();
      }
    }
    qillqa("|");
  }
  qillqa("+--------------------+");
  qillqa("Score:", score, " Record:", record);
  qillqa("[A/D] mover [W] rotar [S] bajar [Q] salir");
}

cursor_visible(0);
record = 0;
yatiya chiqa seguir = chiqa;

ukhakamaxa(seguir) {
  reinicia_partida();

  ukhakamaxa(! fin) {
    yatiya jakhüwi k = tecla();
    ukaxa(k == 113 || k == 81) { fin = chiqa; }

    ukaxa((k == 97 || k == 65 || k == 1003) && ! colisiona(px - 1, py, rot)) { px = px - 1; }
    ukaxa((k == 100 || k == 68 || k == 1004) && ! colisiona(px + 1, py, rot)) { px = px + 1; }
    ukaxa((k == 115 || k == 83 || k == 1002) && ! colisiona(px, py + 1, rot)) { py = py + 1; }
    yatiya chiqa giro_tecla = (k == 119 || k == 87 || k == 1001);
    ukaxa(giro_tecla && giro_listo) {
      yatiya jakhüwi nr = rot + 1;
      ukaxa(nr >= 4) { nr = 0; }
      ukaxa(! colisiona(px, py, nr)) { rot = nr; }
      giro_listo = k'ari;
    }
    ukaxa(! giro_tecla) { giro_listo = chiqa; }

    yatiya jakhüwi ahora = tiempo_ms();
    ukaxa(ahora >= prox_caida) {
      ukaxa(! colisiona(px, py + 1, rot)) {
        py = py + 1;
      } maysatxa {
        fijar_pieza();
        score = score + 10 + limpiar_lineas();
        nueva_pieza();
      }
      prox_caida = ahora + 420;
    }
    dibuja();
    sleep(16);
  }

  ukaxa(score > record) { record = score; }

  cursor_mover(1, ALTO + 8);
  color_restablecer();
  qillqa("GAME OVER");
  qillqa("Score:", score, " Record:", record);
  qillqa("[R] jugar de nuevo  [Q] salir");

  yatiya chiqa espera = chiqa;
  yatiya chiqa opcion_lista = chiqa;
  ukhakamaxa(espera) {
    yatiya jakhüwi tecla_op = tecla();
    yatiya chiqa r_tecla = (tecla_op == 114 || tecla_op == 82);
    yatiya chiqa q_tecla = (tecla_op == 113 || tecla_op == 81);

    ukaxa((r_tecla || q_tecla) && opcion_lista) {
      ukaxa(q_tecla) { seguir = k'ari; }
      espera = k'ari;
      opcion_lista = k'ari;
    }
    ukaxa(! (r_tecla || q_tecla)) { opcion_lista = chiqa; }
    sleep(16);
  }
}

cursor_mover(1, ALTO + 11);
color_restablecer();
cursor_visible(1);
qillqa("Jallalla!");

samples/games/console/katari.aym.source:
yatiya jakhüwi ANCHU = 24;
yatiya jakhüwi SAYA = 16;
yatiya jakhüwi MAXA = ANCHU * SAYA;

yatiya jakhüwi katari_x = array(MAXA);
yatiya jakhüwi katari_y = array(MAXA);
yatiya jakhüwi katari_jaya = 0;

yatiya jakhüwi sarawi_x = 1;
yatiya jakhüwi sarawi_y = 0;
yatiya jakhüwi manqha_x = 0;
yatiya jakhüwi manqha_y = 0;
yatiya jakhüwi puntaje = 0;
yatiya jakhüwi sarawi_pacha = 170;
yatiya jakhüwi jutiri_muyu = 0;
yatiya chiqa tukusi = k'ari;

lurawi utji_katari_kama(jakhüwi x, jakhüwi y, jakhüwi kama): chiqa {
  ukaxa(kama <= 0) { kuttaya k'ari; }
  kuti(yatiya jakhüwi i = 0; i < kama; i = i + 1) {
    ukaxa(array_get(katari_x, i) == x && array_get(katari_y, i) == y) {
      kuttaya chiqa;
    }
  }
  kuttaya k'ari;
}

lurawi manqha_machaqa() {
  yatiya chiqa encontrado = k'ari;
  ukhakamaxa(! encontrado) {
    manqha_x = random(ANCHU);
    manqha_y = random(SAYA);
    ukaxa(! utji_katari_kama(manqha_x, manqha_y, katari_jaya)) {
      encontrado = chiqa;
    }
  }
  kuttaya;
}

lurawi qallta_machaqa() {
  katari_jaya = 4;
  sarawi_x = 1;
  sarawi_y = 0;
  puntaje = 0;
  sarawi_pacha = 170;
  tukusi = k'ari;

  yatiya jakhüwi taypi_x = ANCHU / 2;
  yatiya jakhüwi taypi_y = SAYA / 2;
  kuti(yatiya jakhüwi i = 0; i < katari_jaya; i = i + 1) {
    array_set(katari_x, i, taypi_x - i);
    array_set(katari_y, i, taypi_y);
  }

  manqha_machaqa();
  jutiri_muyu = tiempo_ms() + sarawi_pacha;
  pantalla_limpia();
  kuttaya;
}

lurawi muyu_mayjtaya() {
  yatiya jakhüwi machaqa_x = array_get(katari_x, 0) + sarawi_x;
  yatiya jakhüwi machaqa_y = array_get(katari_y, 0) + sarawi_y;

  ukaxa(machaqa_x < 0 || machaqa_x >= ANCHU || machaqa_y < 0 || machaqa_y >= SAYA) {
    tukusi = chiqa;
    kuttaya;
  }
  ukaxa(utji_katari_kama(machaqa_x, machaqa_y, katari_jaya - 1)) {
    tukusi = chiqa;
    kuttaya;
  }

  kuti(yatiya jakhüwi i = katari_jaya; i > 0; i = i - 1) {
    array_set(katari_x, i, array_get(katari_x, i - 1));
    array_set(katari_y, i, array_get(katari_y, i - 1));
  }
  array_set(katari_x, 0, machaqa_x);
  array_set(katari_y, 0, machaqa_y);

  ukaxa(machaqa_x == manqha_x && machaqa_y == manqha_y) {
    ukaxa(katari_jaya < MAXA - 1) { katari_jaya = katari_jaya + 1; }
    puntaje = puntaje + 10;
    ukaxa(sarawi_pacha > 70) { sarawi_pacha = sarawi_pacha - 4; }
    manqha_machaqa();
  }
  kuttaya;
}

lurawi dibuja() {
  cursor_mover(1, 1);
  qillqa("Katari anatawi");
  write("+");
  kuti(yatiya jakhüwi x0 = 0; x0 < ANCHU; x0 = x0 + 1) { write("--"); }
  qillqa("+");

  kuti(yatiya jakhüwi y = 0; y < SAYA; y = y + 1) {
    write("|");
    kuti(yatiya jakhüwi x = 0; x < ANCHU; x = x + 1) {
      yatiya chiqa pusi = (x == array_get(katari_x, 0) && y == array_get(katari_y, 0));
      yatiya chiqa taypi = utji_katari_kama(x, y, katari_jaya);

      ukaxa(x == manqha_x && y == manqha_y) {
        color(12, 0);
        write("**");
        color_restablecer();
      } maysatxa ukaxa(pusi) {
        color(14, 0);
        write("<>");
        color_restablecer();
      } maysatxa ukaxa(taypi) {
        color(10, 0);
        write("[]");
        color_restablecer();
      } maysatxa {
        write("  ");
      }
    }
    qillqa("|");
  }

  write("+");
  kuti(yatiya jakhüwi x1 = 0; x1 < ANCHU; x1 = x1 + 1) { write("--"); }
  qillqa("+");
  qillqa("Jakhuwi:", puntaje, " Katari:", katari_jaya);
  qillqa("[A/D/W/S] saraya  [Q] mistuña");
  kuttaya;
}

cursor_visible(0);
yatiya chiqa sarantawi = chiqa;

ukhakamaxa(sarantawi) {
  qallta_machaqa();

  ukhakamaxa(! tukusi) {
    yatiya jakhüwi k = tecla();

    ukaxa((k == 97 || k == 65 || k == 1003) && sarawi_x != 1) { sarawi_x = -1; sarawi_y = 0; }
    ukaxa((k == 100 || k == 68 || k == 1004) && sarawi_x != -1) { sarawi_x = 1; sarawi_y = 0; }
    ukaxa((k == 119 || k == 87 || k == 1001) && sarawi_y != 1) { sarawi_x = 0; sarawi_y = -1; }
    ukaxa((k == 115 || k == 83 || k == 1002) && sarawi_y != -1) { sarawi_x = 0; sarawi_y = 1; }
    ukaxa(k == 113 || k == 81) { tukusi = chiqa; sarantawi = k'ari; }

    yatiya jakhüwi jichha = tiempo_ms();
    ukaxa(jichha >= jutiri_muyu) {
      muyu_mayjtaya();
      jutiri_muyu = jichha + sarawi_pacha;
    }

    dibuja();
    sleep(16);
  }

  ukaxa(sarantawi) {
    cursor_mover(1, SAYA + 7);
    color_restablecer();
    qillqa("Tukusiwayi");
    qillqa("Qhipa jakhuwi:", puntaje);
    qillqa("[R] wasitata qallta  [Q] mistuña");

    yatiya chiqa suya = chiqa;
    yatiya chiqa listo = chiqa;
    ukhakamaxa(suya) {
      yatiya jakhüwi ks = tecla();
      yatiya chiqa r_tecla = (ks == 114 || ks == 82);
      yatiya chiqa q_tecla = (ks == 113 || ks == 81);

      ukaxa((r_tecla || q_tecla) && listo) {
        ukaxa(q_tecla) { sarantawi = k'ari; }
        suya = k'ari;
        listo = k'ari;
      }
      ukaxa(! (r_tecla || q_tecla)) { listo = chiqa; }
      sleep(16);
    }
  }
}

cursor_mover(1, SAYA + 10);
color_restablecer();
cursor_visible(1);
qillqa("Jallalla!");

samples/games/console/jamachi.aym.source:
yatiya jakhüwi ANCHU = 34;
yatiya jakhüwi SAYA = 18;
yatiya jakhüwi JAMAX = 8;
yatiya jakhüwi JARKA_JAKHA = 3;
yatiya jakhüwi JARKA_ANCHU = 3;
yatiya jakhüwi CHUSA_JAYA = 5;

yatiya jakhüwi jarka_x = array(JARKA_JAKHA);
yatiya jakhüwi jarka_chusa = array(JARKA_JAKHA);

yatiya jakhüwi jamachi_y = 0;
yatiya jakhüwi chamancha = 0;
yatiya jakhüwi puntaje = 0;
yatiya jakhüwi jutiri = 0;
yatiya chiqa tukusi = k'ari;

lurawi jarkana_jachax(): jakhüwi {
  yatiya jakhüwi jacha = array_get(jarka_x, 0);
  kuti(yatiya jakhüwi i = 1; i < JARKA_JAKHA; i = i + 1) {
    ukaxa(array_get(jarka_x, i) > jacha) { jacha = array_get(jarka_x, i); }
  }
  kuttaya jacha;
}

lurawi jarkana_wakicha(jakhüwi i, jakhüwi qx) {
  array_set(jarka_x, i, qx);
  array_set(jarka_chusa, i, 2 + random(SAYA - CHUSA_JAYA - 3));
  kuttaya;
}

lurawi anatawi_qallta() {
  jamachi_y = SAYA / 2;
  chamancha = 0;
  puntaje = 0;
  tukusi = k'ari;

  kuti(yatiya jakhüwi i = 0; i < JARKA_JAKHA; i = i + 1) {
    jarkana_wakicha(i, ANCHU + i * 12);
  }
  jutiri = tiempo_ms() + 90;
  pantalla_limpia();
  kuttaya;
}

lurawi jarkana_muyu() {
  kuti(yatiya jakhüwi i = 0; i < JARKA_JAKHA; i = i + 1) {
    yatiya jakhüwi x = array_get(jarka_x, i) - 1;
    ukaxa(x + JARKA_ANCHU < 0) {
      x = jarkana_jachax() + 10;
      array_set(jarka_chusa, i, 2 + random(SAYA - CHUSA_JAYA - 3));
      puntaje = puntaje + 1;
    }
    array_set(jarka_x, i, x);
  }
  kuttaya;
}

lurawi tukuriti(): chiqa {
  ukaxa(jamachi_y < 0 || jamachi_y >= SAYA) { kuttaya chiqa; }

  kuti(yatiya jakhüwi i = 0; i < JARKA_JAKHA; i = i + 1) {
    yatiya jakhüwi x = array_get(jarka_x, i);
    yatiya jakhüwi chusa0 = array_get(jarka_chusa, i);
    ukaxa(JAMAX >= x && JAMAX < x + JARKA_ANCHU) {
      ukaxa(jamachi_y < chusa0 || jamachi_y >= chusa0 + CHUSA_JAYA) {
        kuttaya chiqa;
      }
    }
  }
  kuttaya k'ari;
}

lurawi dibuja() {
  cursor_mover(1, 1);
  qillqa("Jamachi anatawi");
  write("+");
  kuti(yatiya jakhüwi x0 = 0; x0 < ANCHU; x0 = x0 + 1) { write("--"); }
  qillqa("+");

  kuti(yatiya jakhüwi y = 0; y < SAYA; y = y + 1) {
    write("|");
    kuti(yatiya jakhüwi x = 0; x < ANCHU; x = x + 1) {
      yatiya chiqa jarkata = k'ari;
      kuti(yatiya jakhüwi i = 0; i < JARKA_JAKHA; i = i + 1) {
        yatiya jakhüwi jx = array_get(jarka_x, i);
        yatiya jakhüwi ch0 = array_get(jarka_chusa, i);
        ukaxa(x >= jx && x < jx + JARKA_ANCHU) {
          ukaxa(y < ch0 || y >= ch0 + CHUSA_JAYA) { jarkata = chiqa; }
        }
      }

      ukaxa(x == JAMAX && y == jamachi_y) {
        color(14, 0);
        write("<>");
        color_restablecer();
      } maysatxa ukaxa(jarkata) {
        color(2, 0);
        write("||");
        color_restablecer();
      } maysatxa {
        write("  ");
      }
    }
    qillqa("|");
  }

  write("+");
  kuti(yatiya jakhüwi x1 = 0; x1 < ANCHU; x1 = x1 + 1) { write("--"); }
  qillqa("+");
  qillqa("Jakhuwi:", puntaje);
  qillqa("[W/UP/ ] thaqta  [Q] mistuña");
  kuttaya;
}

cursor_visible(0);
yatiya chiqa sarantawi = chiqa;

ukhakamaxa(sarantawi) {
  anatawi_qallta();

  ukhakamaxa(! tukusi) {
    yatiya jakhüwi k = tecla();

    ukaxa(k == 113 || k == 81) {
      tukusi = chiqa;
      sarantawi = k'ari;
    }
    ukaxa(k == 119 || k == 87 || k == 1001 || k == 32) {
      chamancha = -3;
    }

    yatiya jakhüwi jichha = tiempo_ms();
    ukaxa(jichha >= jutiri) {
      chamancha = chamancha + 1;
      ukaxa(chamancha > 3) { chamancha = 3; }
      jamachi_y = jamachi_y + chamancha;
      jarkana_muyu();
      ukaxa(tukuriti()) { tukusi = chiqa; }
      jutiri = jichha + 90;
    }

    dibuja();
    sleep(16);
  }

  ukaxa(sarantawi) {
    cursor_mover(1, SAYA + 7);
    color_restablecer();
    qillqa("Tukusiwayi");
    qillqa("Qhipa jakhuwi:", puntaje);
    qillqa("[R] wasitata qallta  [Q] mistuña");

    yatiya chiqa suya = chiqa;
    yatiya chiqa listo = chiqa;
    ukhakamaxa(suya) {
      yatiya jakhüwi ks = tecla();
      yatiya chiqa r_tecla = (ks == 114 || ks == 82);
      yatiya chiqa q_tecla = (ks == 113 || ks == 81);

      ukaxa((r_tecla || q_tecla) && listo) {
        ukaxa(q_tecla) { sarantawi = k'ari; }
        suya = k'ari;
        listo = k'ari;
      }
      ukaxa(! (r_tecla || q_tecla)) { listo = chiqa; }
      sleep(16);
    }
  }
}

cursor_mover(1, SAYA + 10);
color_restablecer();
cursor_visible(1);
qillqa("Jallalla!");

samples/games/console/sudoku_anatawi.aym.source:
yatiya jakhüwi SUYU = 4;
yatiya jakhüwi tabla = 0;
yatiya jakhüwi chinu = 0;
yatiya jakhüwi ajlli_f = 0;
yatiya jakhüwi ajlli_c = 0;
yatiya aru yatiyawi = "";
yatiya chiqa atipi = k'ari;

lurawi fila_machaqa(jakhüwi a, jakhüwi b, jakhüwi c, jakhüwi d): jakhüwi {
  yatiya jakhüwi fila = array(4);
  array_set(fila, 0, a);
  array_set(fila, 1, b);
  array_set(fila, 2, c);
  array_set(fila, 3, d);
  kuttaya fila;
}

lurawi celda_get(jakhüwi tb, jakhüwi f, jakhüwi c): jakhüwi {
  yatiya jakhüwi fila = array_get(tb, f);
  kuttaya array_get(fila, c);
}

lurawi celda_set(jakhüwi tb, jakhüwi f, jakhüwi c, jakhüwi v) {
  yatiya jakhüwi fila = array_get(tb, f);
  array_set(fila, c, v);
  kuttaya;
}

lurawi waliwja(jakhüwi tb, jakhüwi f, jakhüwi c, jakhüwi v): chiqa {
  ukaxa(v < 1 || v > 4) { kuttaya k'ari; }

  kuti(yatiya jakhüwi i = 0; i < 4; i = i + 1) {
    ukaxa(i != c && celda_get(tb, f, i) == v) { kuttaya k'ari; }
    ukaxa(i != f && celda_get(tb, i, c) == v) { kuttaya k'ari; }
  }

  yatiya jakhüwi f0 = (f / 2) * 2;
  yatiya jakhüwi c0 = (c / 2) * 2;
  kuti(yatiya jakhüwi df = 0; df < 2; df = df + 1) {
    kuti(yatiya jakhüwi dc = 0; dc < 2; dc = dc + 1) {
      yatiya jakhüwi ff = f0 + df;
      yatiya jakhüwi cc = c0 + dc;
      ukaxa((ff != f || cc != c) && celda_get(tb, ff, cc) == v) {
        kuttaya k'ari;
      }
    }
  }
  kuttaya chiqa;
}

lurawi phuqhatati(jakhüwi tb): chiqa {
  kuti(yatiya jakhüwi f = 0; f < 4; f = f + 1) {
    kuti(yatiya jakhüwi c = 0; c < 4; c = c + 1) {
      yatiya jakhüwi v = celda_get(tb, f, c);
      ukaxa(v == 0) { kuttaya k'ari; }
      ukaxa(! waliwja(tb, f, c, v)) { kuttaya k'ari; }
    }
  }
  kuttaya chiqa;
}

lurawi anatawi_wakicha() {
  tabla = array(4);
  array_set(tabla, 0, fila_machaqa(1, 0, 0, 4));
  array_set(tabla, 1, fila_machaqa(0, 4, 1, 2));
  array_set(tabla, 2, fila_machaqa(2, 1, 4, 0));
  array_set(tabla, 3, fila_machaqa(4, 0, 2, 1));

  chinu = array(4);
  kuti(yatiya jakhüwi f = 0; f < 4; f = f + 1) {
    yatiya jakhüwi fm = array(4);
    kuti(yatiya jakhüwi c = 0; c < 4; c = c + 1) {
      ukaxa(celda_get(tabla, f, c) == 0) {
        array_set(fm, c, 0);
      } maysatxa {
        array_set(fm, c, 1);
      }
    }
    array_set(chinu, f, fm);
  }

  ajlli_f = 0;
  ajlli_c = 0;
  yatiyawi = "Qallta";
  atipi = k'ari;
  pantalla_limpia();
  kuttaya;
}

lurawi chimpu_mayjtaya(jakhüwi k) {
  yatiya jakhüwi waka = celda_get(chinu, ajlli_f, ajlli_c);
  ukaxa(waka == 1) {
    yatiyawi = "Aka chiqaxa jan mayjtaykanti";
    kuttaya;
  }

  ukaxa(k >= 49 && k <= 52) {
    yatiya jakhüwi v = k - 48;
    ukaxa(waliwja(tabla, ajlli_f, ajlli_c, v)) {
      celda_set(tabla, ajlli_f, ajlli_c, v);
      yatiyawi = "Waliwa";
    } maysatxa {
      yatiyawi = "Jan wali chimpu";
    }
    kuttaya;
  }

  ukaxa(k == 48 || k == 8) {
    celda_set(tabla, ajlli_f, ajlli_c, 0);
    yatiyawi = "Ch'usachata";
  }
  kuttaya;
}

lurawi pintaya() {
  cursor_mover(1, 1);
  qillqa("Suduku anatawi 4x4");
  qillqa("+----+----+");

  kuti(yatiya jakhüwi f = 0; f < 4; f = f + 1) {
    write("|");
    kuti(yatiya jakhüwi c = 0; c < 4; c = c + 1) {
      ukaxa(c == 2) { write("|"); }

      yatiya jakhüwi v = celda_get(tabla, f, c);
      yatiya chiqa waka = (celda_get(chinu, f, c) == 1);
      yatiya chiqa ajlli = (f == ajlli_f && c == ajlli_c);

      ukaxa(ajlli) {
        color(15, 4);
      } maysatxa ukaxa(waka) {
        color(11, 0);
      } maysatxa {
        color_restablecer();
      }

      ukaxa(v == 0) {
        write(". ");
      } maysatxa {
        write(aru(v));
        write(" ");
      }
      color_restablecer();
    }
    qillqa("|");
    ukaxa(f == 1) { qillqa("+----+----+"); }
  }

  qillqa("+----+----+");
  qillqa("[A/D/W/S] saraya  [1..4] uchanta  [0] pichha  [Q] mistuña");
  qillqa("Yatiyawi:", yatiyawi);
  kuttaya;
}

cursor_visible(0);
yatiya chiqa sarantawi = chiqa;

ukhakamaxa(sarantawi) {
  anatawi_wakicha();
  yatiya chiqa tukusi = k'ari;

  ukhakamaxa(! tukusi) {
    yatiya jakhüwi k = tecla();

    ukaxa(k == 97 || k == 65 || k == 1003) { ukaxa(ajlli_c > 0) { ajlli_c = ajlli_c - 1; } }
    ukaxa(k == 100 || k == 68 || k == 1004) { ukaxa(ajlli_c < 3) { ajlli_c = ajlli_c + 1; } }
    ukaxa(k == 119 || k == 87 || k == 1001) { ukaxa(ajlli_f > 0) { ajlli_f = ajlli_f - 1; } }
    ukaxa(k == 115 || k == 83 || k == 1002) { ukaxa(ajlli_f < 3) { ajlli_f = ajlli_f + 1; } }

    ukaxa(k == 113 || k == 81) {
      tukusi = chiqa;
      sarantawi = k'ari;
    }

    ukaxa((k >= 48 && k <= 52) || k == 8) {
      chimpu_mayjtaya(k);
    }

    ukaxa(phuqhatati(tabla)) {
      tukusi = chiqa;
      atipi = chiqa;
      yatiyawi = "Atiptawa";
    }

    pintaya();
    sleep(16);
  }

  ukaxa(sarantawi) {
    cursor_mover(1, 11);
    color_restablecer();
    ukaxa(atipi) {
      qillqa("Atiptawa!");
    } maysatxa {
      qillqa("Tukusiwayi");
    }
    qillqa("[R] wasitata qallta  [Q] mistuña");

    yatiya chiqa suya = chiqa;
    yatiya chiqa listo = chiqa;
    ukhakamaxa(suya) {
      yatiya jakhüwi ks = tecla();
      yatiya chiqa r_tecla = (ks == 114 || ks == 82);
      yatiya chiqa q_tecla = (ks == 113 || ks == 81);

      ukaxa((r_tecla || q_tecla) && listo) {
        ukaxa(q_tecla) { sarantawi = k'ari; }
        suya = k'ari;
        listo = k'ari;
      }
      ukaxa(! (r_tecla || q_tecla)) { listo = chiqa; }
      sleep(16);
    }
  }
}

cursor_mover(1, 14);
color_restablecer();
cursor_visible(1);
qillqa("Jallalla!");

samples/games/gui/tetris.aym.source:
yatiya jakhüwi UJA_ANCHU = 520;
yatiya jakhüwi UJA_SAYA = 620;
yatiya jakhüwi CELDA = 24;
yatiya jakhüwi CELDA_PREV = 16;
yatiya jakhüwi ANCHO = 10;
yatiya jakhüwi ALTO = 20;
yatiya jakhüwi OX = 80;
yatiya jakhüwi OY = 70;

yatiya jakhüwi tablero = 0;
yatiya jakhüwi marcador = 0;
yatiya jakhüwi mejor = 0;
yatiya chiqa fin = k'ari;

yatiya jakhüwi px = 4;
yatiya jakhüwi py = 0;
yatiya jakhüwi tipo = 0;
yatiya jakhüwi rot = 0;
yatiya jakhüwi color_pieza = 1;
yatiya jakhüwi proximo = 0;
yatiya chiqa giro_listo = chiqa;
yatiya jakhüwi proximo_tipo = 0;
yatiya jakhüwi proximo_rot = 0;
yatiya jakhüwi proximo_color = 1;

lurawi nuevo_tablero(): jakhüwi {
  yatiya jakhüwi tb = array(ALTO);
  kuti(yatiya jakhüwi y = 0; y < ALTO; y = y + 1) {
    yatiya jakhüwi fila = array(ANCHO);
    kuti(yatiya jakhüwi x = 0; x < ANCHO; x = x + 1) {
      array_set(fila, x, 0);
    }
    array_set(tb, y, fila);
  }
  kuttaya tb;
}

lurawi tablero_get(jakhüwi x, jakhüwi y): jakhüwi {
  yatiya jakhüwi fila = array_get(tablero, y);
  kuttaya array_get(fila, x);
}

lurawi tablero_set(jakhüwi x, jakhüwi y, jakhüwi v) {
  yatiya jakhüwi fila = array_get(tablero, y);
  array_set(fila, x, v);
  kuttaya;
}

// tipo: 0=I, 1=O, 2=T, 3=L, 4=S
lurawi p_dx(jakhüwi t, jakhüwi r, jakhüwi i): jakhüwi {
  ukaxa(t == 0) {
    ukaxa(r == 0 || r == 2) { kuttaya i; }
    kuttaya 1;
  }
  ukaxa(t == 1) {
    ukaxa(i == 0 || i == 2) { kuttaya 0; }
    kuttaya 1;
  }
  ukaxa(t == 2) {
    ukaxa(r == 0) { ukaxa(i == 0) { kuttaya 1; } ukaxa(i == 1) { kuttaya 0; } ukaxa(i == 2) { kuttaya 1; } kuttaya 2; }
    ukaxa(r == 1) { ukaxa(i == 0) { kuttaya 1; } ukaxa(i == 1) { kuttaya 1; } ukaxa(i == 2) { kuttaya 1; } kuttaya 2; }
    ukaxa(r == 2) { ukaxa(i == 0) { kuttaya 0; } ukaxa(i == 1) { kuttaya 1; } ukaxa(i == 2) { kuttaya 2; } kuttaya 1; }
    ukaxa(i == 0) { kuttaya 0; } ukaxa(i == 1) { kuttaya 1; } ukaxa(i == 2) { kuttaya 1; } kuttaya 1;
  }
  ukaxa(t == 3) {
    ukaxa(r == 0) { ukaxa(i == 0) { kuttaya 0; } ukaxa(i == 1) { kuttaya 0; } ukaxa(i == 2) { kuttaya 1; } kuttaya 2; }
    ukaxa(r == 1) { ukaxa(i == 0) { kuttaya 1; } ukaxa(i == 1) { kuttaya 2; } ukaxa(i == 2) { kuttaya 1; } kuttaya 1; }
    ukaxa(r == 2) { ukaxa(i == 0) { kuttaya 0; } ukaxa(i == 1) { kuttaya 1; } ukaxa(i == 2) { kuttaya 2; } kuttaya 2; }
    ukaxa(i == 0) { kuttaya 1; } ukaxa(i == 1) { kuttaya 1; } ukaxa(i == 2) { kuttaya 0; } kuttaya 1;
  }
  // S
  ukaxa(r == 0 || r == 2) {
    ukaxa(i == 0) { kuttaya 1; } ukaxa(i == 1) { kuttaya 2; } ukaxa(i == 2) { kuttaya 0; } kuttaya 1;
  }
  ukaxa(i == 0) { kuttaya 1; } ukaxa(i == 1) { kuttaya 1; } ukaxa(i == 2) { kuttaya 2; } kuttaya 2;
}

lurawi p_dy(jakhüwi t, jakhüwi r, jakhüwi i): jakhüwi {
  ukaxa(t == 0) {
    ukaxa(r == 0 || r == 2) { kuttaya 1; }
    kuttaya i;
  }
  ukaxa(t == 1) {
    ukaxa(i < 2) { kuttaya 0; } kuttaya 1;
  }
  ukaxa(t == 2) {
    ukaxa(r == 0) { ukaxa(i == 0) { kuttaya 0; } ukaxa(i == 1) { kuttaya 1; } ukaxa(i == 2) { kuttaya 1; } kuttaya 1; }
    ukaxa(r == 1) { ukaxa(i == 0) { kuttaya 0; } ukaxa(i == 1) { kuttaya 1; } ukaxa(i == 2) { kuttaya 2; } kuttaya 1; }
    ukaxa(r == 2) { ukaxa(i == 0) { kuttaya 1; } ukaxa(i == 1) { kuttaya 1; } ukaxa(i == 2) { kuttaya 1; } kuttaya 2; }
    ukaxa(i == 0) { kuttaya 1; } ukaxa(i == 1) { kuttaya 0; } ukaxa(i == 2) { kuttaya 1; } kuttaya 2;
  }
  ukaxa(t == 3) {
    ukaxa(r == 0) { ukaxa(i == 0) { kuttaya 0; } ukaxa(i == 1) { kuttaya 1; } ukaxa(i == 2) { kuttaya 1; } kuttaya 1; }
    ukaxa(r == 1) { ukaxa(i == 0) { kuttaya 0; } ukaxa(i == 1) { kuttaya 0; } ukaxa(i == 2) { kuttaya 1; } kuttaya 2; }
    ukaxa(r == 2) { ukaxa(i == 0) { kuttaya 1; } ukaxa(i == 1) { kuttaya 1; } ukaxa(i == 2) { kuttaya 1; } kuttaya 2; }
    ukaxa(i == 0) { kuttaya 0; } ukaxa(i == 1) { kuttaya 1; } ukaxa(i == 2) { kuttaya 2; } kuttaya 2;
  }
  // S
  ukaxa(r == 0 || r == 2) {
    ukaxa(i == 0) { kuttaya 0; } ukaxa(i == 1) { kuttaya 0; } ukaxa(i == 2) { kuttaya 1; } kuttaya 1;
  }
  ukaxa(i == 0) { kuttaya 0; } ukaxa(i == 1) { kuttaya 1; } ukaxa(i == 2) { kuttaya 1; } kuttaya 2;
}

lurawi es_bloque(jakhüwi x, jakhüwi y, jakhüwi cx, jakhüwi cy): chiqa {
  kuti(yatiya jakhüwi i = 0; i < 4; i = i + 1) {
    ukaxa(x == cx + p_dx(tipo, rot, i) && y == cy + p_dy(tipo, rot, i)) { kuttaya chiqa; }
  }
  kuttaya k'ari;
}

lurawi colision(jakhüwi cx, jakhüwi cy, jakhüwi cr): chiqa {
  kuti(yatiya jakhüwi i = 0; i < 4; i = i + 1) {
    yatiya jakhüwi x = cx + p_dx(tipo, cr, i);
    yatiya jakhüwi y = cy + p_dy(tipo, cr, i);
    ukaxa(x < 0 || x >= ANCHO || y < 0 || y >= ALTO) { kuttaya chiqa; }
    ukaxa(tablero_get(x, y) != 0) { kuttaya chiqa; }
  }
  kuttaya k'ari;
}

lurawi fijar_pieza() {
  kuti(yatiya jakhüwi i = 0; i < 4; i = i + 1) {
    tablero_set(px + p_dx(tipo, rot, i), py + p_dy(tipo, rot, i), color_pieza);
  }
  kuttaya;
}

lurawi limpiar_lineas(): jakhüwi {
  yatiya jakhüwi puntos = 0;
  kuti(yatiya jakhüwi y = ALTO - 1; y >= 0; y = y - 1) {
    yatiya chiqa llena = chiqa;
    kuti(yatiya jakhüwi x = 0; x < ANCHO; x = x + 1) {
      ukaxa(tablero_get(x, y) == 0) {
        llena = k'ari;
      }
    }
    ukaxa(llena) {
      puntos = puntos + 100;
      kuti(yatiya jakhüwi yy = y; yy > 0; yy = yy - 1) {
        kuti(yatiya jakhüwi x2 = 0; x2 < ANCHO; x2 = x2 + 1) {
          tablero_set(x2, yy, tablero_get(x2, yy - 1));
        }
      }
      kuti(yatiya jakhüwi x3 = 0; x3 < ANCHO; x3 = x3 + 1) {
        tablero_set(x3, 0, 0);
      }
      y = y + 1;
    }
  }
  kuttaya puntos;
}

lurawi pinta_bloque_tam(jakhüwi sx, jakhüwi sy, jakhüwi tam, jakhüwi v) {
  yatiya jakhüwi rr = 255;
  yatiya jakhüwi gg = 202;
  yatiya jakhüwi bb = 58;

  ukaxa(v == 2) {
    rr = 90;
    gg = 180;
    bb = 255;
  } maysatxa ukaxa(v == 3) {
    rr = 239;
    gg = 108;
    bb = 146;
  } maysatxa ukaxa(v == 4) {
    rr = 136;
    gg = 220;
    bb = 118;
  } maysatxa ukaxa(v == 5) {
    rr = 255;
    gg = 150;
    bb = 86;
  } maysatxa ukaxa(v == 6) {
    rr = 186;
    gg = 150;
    bb = 255;
  }

  uja_suyu(sx + 2, sy + 2, tam - 4, tam - 4, rr, gg, bb);
  kuttaya;
}

lurawi pinta_bloque(jakhüwi sx, jakhüwi sy, jakhüwi v) {
  pinta_bloque_tam(sx, sy, CELDA, v);
  kuttaya;
}

lurawi dibuja() {
  uja_pichha(14, 18, 26);

  uja_qillqa("Tetris Uja", 18, 16, 245, 245, 245);
  yatiya aru s1 = "Jakhuwi: " + aru(marcador);
  yatiya aru s2 = "Mejor: " + aru(mejor);
  uja_qillqa(s1, 18, 40, 215, 236, 196);
  uja_qillqa(s2, 180, 40, 189, 214, 255);
  uja_qillqa("A/D saraya  W muytiya  S jalaqaya  Q/Esc mistuña  R wasitata", 18, 590, 173, 190, 212);

  uja_suyu(OX - 4, OY - 4, ANCHO * CELDA + 8, ALTO * CELDA + 8, 186, 198, 208);

  kuti(yatiya jakhüwi y = 0; y < ALTO; y = y + 1) {
    kuti(yatiya jakhüwi x = 0; x < ANCHO; x = x + 1) {
      yatiya jakhüwi sx = OX + x * CELDA;
      yatiya jakhüwi sy = OY + y * CELDA;
      yatiya jakhüwi v = tablero_get(x, y);

      uja_suyu(sx + 1, sy + 1, CELDA - 2, CELDA - 2, 26, 32, 45);

      ukaxa(es_bloque(x, y, px, py) && ! fin) {
        pinta_bloque(sx, sy, color_pieza);
      } maysatxa ukaxa(v != 0) {
        pinta_bloque(sx, sy, v);
      }
    }
  }

  yatiya jakhüwi panel_x = OX + ANCHO * CELDA + 24;
  yatiya jakhüwi panel_y = OY + 36;
  yatiya jakhüwi panel_w = 146;
  yatiya jakhüwi panel_h = 150;

  uja_suyu(panel_x - 4, panel_y - 30, panel_w + 8, panel_h + 36, 186, 198, 208);
  uja_suyu(panel_x, panel_y, panel_w, panel_h, 20, 27, 40);
  uja_qillqa("Jutiri pieza", panel_x + 14, panel_y - 20, 225, 235, 248);

  kuti(yatiya jakhüwi gy = 0; gy < 6; gy = gy + 1) {
    kuti(yatiya jakhüwi gx = 0; gx < 6; gx = gx + 1) {
      yatiya jakhüwi csx = panel_x + 10 + gx * CELDA_PREV;
      yatiya jakhüwi csy = panel_y + 10 + gy * CELDA_PREV;
      uja_suyu(csx + 1, csy + 1, CELDA_PREV - 2, CELDA_PREV - 2, 26, 32, 45);
    }
  }

  kuti(yatiya jakhüwi i = 0; i < 4; i = i + 1) {
    yatiya jakhüwi dx = p_dx(proximo_tipo, proximo_rot, i);
    yatiya jakhüwi dy = p_dy(proximo_tipo, proximo_rot, i);
    yatiya jakhüwi psx = panel_x + 10 + (dx + 1) * CELDA_PREV;
    yatiya jakhüwi psy = panel_y + 10 + (dy + 1) * CELDA_PREV;
    pinta_bloque_tam(psx, psy, CELDA_PREV, proximo_color);
  }

  ukaxa(fin) {
    uja_suyu(114, 292, 292, 92, 10, 12, 18);
    uja_qillqa("Tukusiwayi", 210, 320, 255, 105, 105);
    uja_qillqa("R wasitata | Q mistuña", 168, 350, 220, 226, 232);
  }

  uja_ustaya();
  kuttaya;
}

lurawi prepara_siguiente() {
  proximo_tipo = random(5);
  proximo_rot = random(4);
  proximo_color = 1 + random(6);
  kuttaya;
}

lurawi nueva_pieza() {
  tipo = proximo_tipo;
  rot = proximo_rot;
  px = 3;
  py = 0;
  color_pieza = proximo_color;
  prepara_siguiente();
  ukaxa(colision(px, py, rot)) {
    fin = chiqa;
  }
  kuttaya;
}

lurawi reinicia() {
  tablero = nuevo_tablero();
  marcador = 0;
  fin = k'ari;
  giro_listo = chiqa;
  px = 4;
  py = 0;
  tipo = 0;
  rot = 0;
  color_pieza = 1;
  proximo_tipo = 0;
  proximo_rot = 0;
  proximo_color = 1;
  prepara_siguiente();
  nueva_pieza();
  proximo = tiempo_ms() + 420;
  kuttaya;
}

yatiya chiqa sarantawi = uja_qallta(UJA_ANCHU, UJA_SAYA, "Tetris Uja");

ukaxa(sarantawi) {
  reinicia();

  ukhakamaxa(sarantawi && uja_utji()) {
    yatiya jakhüwi k = tecla();

    yatiya chiqa ima_a = (k == 97 || k == 65 || k == 1003 || uja_tecla(97) || uja_tecla(65) || uja_tecla(1003));
    yatiya chiqa ima_d = (k == 100 || k == 68 || k == 1004 || uja_tecla(100) || uja_tecla(68) || uja_tecla(1004));
    yatiya chiqa ima_w = (k == 119 || k == 87 || k == 1001 || uja_tecla(119) || uja_tecla(87) || uja_tecla(1001));
    yatiya chiqa ima_s = (k == 115 || k == 83 || k == 1002 || uja_tecla(115) || uja_tecla(83) || uja_tecla(1002));
    yatiya chiqa ima_q = (k == 113 || k == 81 || k == 27 || uja_tecla(113) || uja_tecla(81) || uja_tecla(27));
    yatiya chiqa ima_r = (k == 114 || k == 82 || uja_tecla(114) || uja_tecla(82));

    ukaxa(ima_q) {
      sarantawi = k'ari;
    }

    ukaxa(fin) {
      ukaxa(ima_r) {
        reinicia();
      }
    } maysatxa {
      ukaxa(ima_a && ! colision(px - 1, py, rot)) { px = px - 1; }
      ukaxa(ima_d && ! colision(px + 1, py, rot)) { px = px + 1; }
      ukaxa(ima_s && ! colision(px, py + 1, rot)) { py = py + 1; }

      ukaxa(ima_w && giro_listo) {
        yatiya jakhüwi nr = rot + 1;
        ukaxa(nr >= 4) { nr = 0; }
        ukaxa(! colision(px, py, nr)) { rot = nr; }
        giro_listo = k'ari;
      }
      ukaxa(! ima_w) { giro_listo = chiqa; }

      yatiya jakhüwi ahora = tiempo_ms();
      ukaxa(ahora >= proximo) {
        ukaxa(! colision(px, py + 1, rot)) {
          py = py + 1;
        } maysatxa {
          fijar_pieza();
          marcador = marcador + 10 + limpiar_lineas();
          ukaxa(marcador > mejor) { mejor = marcador; }

          nueva_pieza();
        }
        proximo = ahora + 420;
      }
    }

    dibuja();
    sleep(16);
  }

  uja_tukuya();
}

qillqa("Jallalla!");

samples/games/gui/katari_uja.aym.source:
yatiya jakhüwi UJA_ANCHU = 768;
yatiya jakhüwi UJA_SAYA = 576;
yatiya jakhüwi CELDA = 24;
yatiya jakhüwi ANCHU = UJA_ANCHU / CELDA;
yatiya jakhüwi SAYA = UJA_SAYA / CELDA;
yatiya jakhüwi MAXA = ANCHU * SAYA;

yatiya jakhüwi katari_x = array(MAXA);
yatiya jakhüwi katari_y = array(MAXA);
yatiya jakhüwi katari_jaya = 0;

yatiya jakhüwi sarawi_x = 1;
yatiya jakhüwi sarawi_y = 0;
yatiya jakhüwi manqha_x = 0;
yatiya jakhüwi manqha_y = 0;
yatiya jakhüwi puntaje = 0;
yatiya jakhüwi sarawi_pacha = 120;
yatiya jakhüwi jutiri_muyu = 0;
yatiya chiqa tukusi = k'ari;

lurawi utji_katari_kama(jakhüwi x, jakhüwi y, jakhüwi kama): chiqa {
  ukaxa(kama <= 0) { kuttaya k'ari; }
  yatiya jakhüwi i = 0;
  ukhakamaxa(i < kama) {
    ukaxa(array_get(katari_x, i) == x && array_get(katari_y, i) == y) {
      kuttaya chiqa;
    }
    i = i + 1;
  }
  kuttaya k'ari;
}

lurawi manqha_machaqa() {
  yatiya chiqa jikjata = k'ari;
  yatiya jakhüwi intento = 0;
  yatiya jakhüwi limite = MAXA * 2;
  ukhakamaxa(! jikjata) {
    ukaxa(intento >= limite) {
      manqha_x = 0;
      manqha_y = 0;
      jikjata = chiqa;
    } maysatxa {
    manqha_x = random(ANCHU);
    manqha_y = random(SAYA);
    ukaxa(! utji_katari_kama(manqha_x, manqha_y, katari_jaya)) {
      jikjata = chiqa;
    }
    intento = intento + 1;
    }
  }
  kuttaya;
}

lurawi qallta_machaqa() {
  katari_jaya = 5;
  sarawi_x = 1;
  sarawi_y = 0;
  puntaje = 0;
  sarawi_pacha = 120;
  tukusi = k'ari;

  yatiya jakhüwi taypi_x = ANCHU / 2;
  yatiya jakhüwi taypi_y = SAYA / 2;
  yatiya jakhüwi i = 0;
  ukhakamaxa(i < katari_jaya) {
    array_set(katari_x, i, taypi_x - i);
    array_set(katari_y, i, taypi_y);
    i = i + 1;
  }

  manqha_machaqa();
  jutiri_muyu = tiempo_ms() + sarawi_pacha;
  kuttaya;
}

lurawi muyu_mayjtaya() {
  yatiya jakhüwi machaqa_x = array_get(katari_x, 0) + sarawi_x;
  yatiya jakhüwi machaqa_y = array_get(katari_y, 0) + sarawi_y;

  ukaxa(machaqa_x < 0 || machaqa_x >= ANCHU || machaqa_y < 0 || machaqa_y >= SAYA) {
    tukusi = chiqa;
    kuttaya;
  }

  yatiya chiqa manqha_apthapi = (machaqa_x == manqha_x && machaqa_y == manqha_y);
  yatiya jakhüwi jani_saranta = katari_jaya - 1;
  ukaxa(manqha_apthapi) { jani_saranta = katari_jaya; }

  ukaxa(utji_katari_kama(machaqa_x, machaqa_y, jani_saranta)) {
    tukusi = chiqa;
    kuttaya;
  }

  yatiya jakhüwi limite = katari_jaya - 1;
  ukaxa(manqha_apthapi && katari_jaya < MAXA - 1) {
    limite = katari_jaya;
    katari_jaya = katari_jaya + 1;
  }

  yatiya jakhüwi i = limite;
  ukhakamaxa(i > 0) {
    array_set(katari_x, i, array_get(katari_x, i - 1));
    array_set(katari_y, i, array_get(katari_y, i - 1));
    i = i - 1;
  }

  array_set(katari_x, 0, machaqa_x);
  array_set(katari_y, 0, machaqa_y);

  ukaxa(manqha_apthapi) {
    puntaje = puntaje + 10;
    ukaxa(sarawi_pacha > 55) { sarawi_pacha = sarawi_pacha - 3; }
    manqha_machaqa();
  }
  kuttaya;
}

lurawi dibuja_anatawi() {
  uja_pichha(16, 18, 28);
  uja_suyu(0, 0, UJA_ANCHU, UJA_SAYA, 22, 26, 38);

  yatiya jakhüwi mx = manqha_x * CELDA;
  yatiya jakhüwi my = manqha_y * CELDA;
  uja_suyu(mx + 2, my + 2, CELDA - 4, CELDA - 4, 232, 74, 86);

  yatiya jakhüwi hx = array_get(katari_x, 0) * CELDA;
  yatiya jakhüwi hy = array_get(katari_y, 0) * CELDA;
  uja_suyu(hx + 2, hy + 2, CELDA - 4, CELDA - 4, 250, 194, 53);
  uja_suyu(hx + 7, hy + 7, CELDA - 14, CELDA - 14, 232, 121, 28);

  yatiya jakhüwi i = 1;
  ukhakamaxa(i < katari_jaya) {
    yatiya jakhüwi x = array_get(katari_x, i) * CELDA;
    yatiya jakhüwi y = array_get(katari_y, i) * CELDA;
    uja_suyu(x + 3, y + 3, CELDA - 6, CELDA - 6, 84, 205, 126);
    i = i + 1;
  }

  yatiya aru s = "Jakhuwi: " + aru(puntaje);
  uja_qillqa("Katari Uja", 10, 8, 245, 245, 245);
  uja_qillqa(s, 10, 30, 221, 238, 199);
  uja_qillqa("A/D/W/S jan ukaxa flecha | Q/Esc mistuña", 10, UJA_SAYA - 28, 183, 202, 210);
  uja_ustaya();
  kuttaya;
}

lurawi dibuja_tukusi() {
  dibuja_anatawi();
  uja_suyu(140, 210, 490, 140, 10, 12, 18);
  uja_qillqa("Tukusiwayi", 322, 245, 255, 95, 95);
  yatiya aru s = "Qhipa jakhuwi: " + aru(puntaje);
  uja_qillqa(s, 280, 276, 236, 236, 236);
  uja_qillqa("R wasitata qallta | Q/Esc mistuña", 240, 308, 190, 214, 190);
  uja_ustaya();
  kuttaya;
}

yatiya chiqa sarantawi = uja_qallta(UJA_ANCHU, UJA_SAYA, "Katari Uja");

ukhakamaxa(sarantawi && uja_utji()) {
  qallta_machaqa();
  dibuja_anatawi();

  ukhakamaxa(sarantawi && uja_utji() && ! tukusi) {
    yatiya jakhüwi k = tecla();
    yatiya chiqa ima_a = (k == 97 || k == 65 || k == 1003 || uja_tecla(97) || uja_tecla(65) || uja_tecla(1003));
    yatiya chiqa ima_d = (k == 100 || k == 68 || k == 1004 || uja_tecla(100) || uja_tecla(68) || uja_tecla(1004));
    yatiya chiqa ima_w = (k == 119 || k == 87 || k == 1001 || uja_tecla(119) || uja_tecla(87) || uja_tecla(1001));
    yatiya chiqa ima_s = (k == 115 || k == 83 || k == 1002 || uja_tecla(115) || uja_tecla(83) || uja_tecla(1002));
    yatiya chiqa ima_q = (k == 113 || k == 81 || k == 27 || uja_tecla(113) || uja_tecla(81) || uja_tecla(27));

    ukaxa(ima_a && sarawi_x != 1) { sarawi_x = -1; sarawi_y = 0; }
    ukaxa(ima_d && sarawi_x != -1) { sarawi_x = 1; sarawi_y = 0; }
    ukaxa(ima_w && sarawi_y != 1) { sarawi_x = 0; sarawi_y = -1; }
    ukaxa(ima_s && sarawi_y != -1) { sarawi_x = 0; sarawi_y = 1; }

    ukaxa(ima_q) {
      sarantawi = k'ari;
    }

    yatiya jakhüwi jichha = tiempo_ms();
    ukaxa(jichha >= jutiri_muyu) {
      muyu_mayjtaya();
      jutiri_muyu = jichha + sarawi_pacha;
    }

    dibuja_anatawi();
    sleep(16);
  }

  yatiya chiqa listo = chiqa;
  ukhakamaxa(sarantawi && uja_utji() && tukusi) {
    yatiya jakhüwi ks = tecla();
    yatiya chiqa r_tecla = (ks == 82 || ks == 114 || uja_tecla(82) || uja_tecla(114));
    yatiya chiqa q_tecla = (ks == 81 || ks == 113 || ks == 27 || uja_tecla(81) || uja_tecla(113) || uja_tecla(27));

    ukaxa((r_tecla || q_tecla) && listo) {
      ukaxa(q_tecla) { sarantawi = k'ari; }
      ukaxa(r_tecla) { tukusi = k'ari; }
      listo = k'ari;
    }

    ukaxa(! (r_tecla || q_tecla)) {
      listo = chiqa;
    }

    dibuja_tukusi();
    sleep(16);
  }
}

uja_tukuya();
qillqa("Jallalla!");

samples/games/gui/jamachi_uja.aym.source:
yatiya jakhüwi UJA_ANCHU = 816;
yatiya jakhüwi UJA_SAYA = 432;
yatiya jakhüwi CELDA = 24;

yatiya jakhüwi ANCHU = 34;
yatiya jakhüwi SAYA = 15;
yatiya jakhüwi JAMAX = 8;
yatiya jakhüwi JARKA_JAKHA = 3;
yatiya jakhüwi JARKA_ANCHU = 3;
yatiya jakhüwi CHUSA_JAYA = 5;
yatiya jakhüwi CHUSA_MIN = 3;

yatiya jakhüwi jarka_x = array(JARKA_JAKHA);
yatiya jakhüwi jarka_chusa = array(JARKA_JAKHA);
yatiya jakhüwi jarka_chusa_jaya = array(JARKA_JAKHA);

yatiya jakhüwi jamachi_y = 0;
yatiya jakhüwi chamancha = 0;
yatiya jakhüwi puntaje = 0;
yatiya jakhüwi mejor = 0;
yatiya jakhüwi jutiri = 0;
yatiya chiqa tukusi = k'ari;
yatiya chiqa thaqta_listo = chiqa;
yatiya chiqa pausa = k'ari;
yatiya chiqa pausa_listo = chiqa;

lurawi jarkana_jachax(): jakhüwi {
  yatiya jakhüwi jacha = array_get(jarka_x, 0);
  kuti(yatiya jakhüwi i = 1; i < JARKA_JAKHA; i = i + 1) {
    ukaxa(array_get(jarka_x, i) > jacha) { jacha = array_get(jarka_x, i); }
  }
  kuttaya jacha;
}

lurawi chusa_jichha(): jakhüwi {
  yatiya jakhüwi g = CHUSA_JAYA;
  ukaxa(puntaje >= 10) { g = 4; }
  ukaxa(puntaje >= 22) { g = CHUSA_MIN; }
  kuttaya g;
}

lurawi ritmo_jichha(): jakhüwi {
  yatiya jakhüwi r = 90 - (puntaje / 4) * 3;
  ukaxa(r < 58) { r = 58; }
  kuttaya r;
}

lurawi nivel_jichha(): jakhüwi {
  yatiya jakhüwi n = 1 + puntaje / 8;
  ukaxa(n > 9) { n = 9; }
  kuttaya n;
}

lurawi jarkana_wakicha(jakhüwi i, jakhüwi qx) {
  yatiya jakhüwi chusa = chusa_jichha();
  yatiya jakhüwi max0 = SAYA - chusa - 3;
  ukaxa(max0 < 1) { max0 = 1; }
  array_set(jarka_x, i, qx);
  array_set(jarka_chusa, i, 2 + random(max0));
  array_set(jarka_chusa_jaya, i, chusa);
  kuttaya;
}

lurawi anatawi_qallta() {
  jamachi_y = SAYA / 2;
  chamancha = 0;
  puntaje = 0;
  tukusi = k'ari;
  thaqta_listo = chiqa;
  pausa = k'ari;
  pausa_listo = chiqa;

  kuti(yatiya jakhüwi i = 0; i < JARKA_JAKHA; i = i + 1) {
    jarkana_wakicha(i, ANCHU + i * 12);
  }
  jutiri = tiempo_ms() + ritmo_jichha();
  kuttaya;
}

lurawi jarkana_muyu() {
  kuti(yatiya jakhüwi i = 0; i < JARKA_JAKHA; i = i + 1) {
    yatiya jakhüwi x = array_get(jarka_x, i) - 1;
    ukaxa(x + JARKA_ANCHU < 0) {
      jarkana_wakicha(i, jarkana_jachax() + 10);
      x = array_get(jarka_x, i);
      puntaje = puntaje + 1;
      ukaxa(puntaje > mejor) { mejor = puntaje; }
    }
    array_set(jarka_x, i, x);
  }
  kuttaya;
}

lurawi tukuriti(): chiqa {
  ukaxa(jamachi_y < 0 || jamachi_y >= SAYA) { kuttaya chiqa; }

  kuti(yatiya jakhüwi i = 0; i < JARKA_JAKHA; i = i + 1) {
    yatiya jakhüwi x = array_get(jarka_x, i);
    yatiya jakhüwi chusa0 = array_get(jarka_chusa, i);
    yatiya jakhüwi chusa = array_get(jarka_chusa_jaya, i);
    ukaxa(JAMAX >= x && JAMAX < x + JARKA_ANCHU) {
      ukaxa(jamachi_y < chusa0 || jamachi_y >= chusa0 + chusa) {
        kuttaya chiqa;
      }
    }
  }
  kuttaya k'ari;
}

lurawi pinta_fondo() {
  uja_pichha(82, 162, 235);
  uja_suyu(0, UJA_SAYA - 72, UJA_ANCHU, 72, 62, 128, 86);
  kuttaya;
}

lurawi dibuja() {
  pinta_fondo();

  kuti(yatiya jakhüwi i = 0; i < JARKA_JAKHA; i = i + 1) {
    yatiya jakhüwi xg = array_get(jarka_x, i) * CELDA;
    yatiya jakhüwi ch0 = array_get(jarka_chusa, i);
    yatiya jakhüwi chusa = array_get(jarka_chusa_jaya, i);

    yatiya jakhüwi top_h = ch0 * CELDA;
    yatiya jakhüwi bot_y = (ch0 + chusa) * CELDA;
    yatiya jakhüwi bot_h = UJA_SAYA - 72 - bot_y;

    uja_suyu(xg, 0, JARKA_ANCHU * CELDA, top_h, 74, 160, 92);
    ukaxa(bot_h > 0) {
      uja_suyu(xg, bot_y, JARKA_ANCHU * CELDA, bot_h, 74, 160, 92);
    }
  }

  yatiya jakhüwi bx = JAMAX * CELDA + 4;
  yatiya jakhüwi by = jamachi_y * CELDA + 4;
  uja_suyu(bx, by, CELDA - 8, CELDA - 8, 252, 210, 88);
  uja_suyu(bx + 14, by + 8, 6, 6, 24, 28, 36);

  uja_qillqa("Jamachi Uja", 12, 10, 248, 248, 248);
  yatiya aru s1 = "Jakhuwi: " + aru(puntaje);
  yatiya aru s2 = "Mejor: " + aru(mejor);
  yatiya aru s3 = "Nivel: " + aru(nivel_jichha());
  yatiya aru s4 = "Ritmo: " + aru(ritmo_jichha()) + "ms";
  uja_qillqa(s1, 12, 34, 238, 247, 222);
  uja_qillqa(s2, 166, 34, 222, 236, 255);
  uja_qillqa(s3, 314, 34, 254, 226, 168);
  uja_qillqa(s4, 442, 34, 202, 238, 212);
  uja_qillqa("W/UP/SPACE thaqta | P samart'aya | R wasitata | Q/Esc mistuña", 12, UJA_SAYA - 28, 236, 244, 252);

  ukaxa(tukusi) {
    uja_suyu(236, 162, 350, 108, 18, 26, 38);
    uja_qillqa("Tukusiwayi", 350, 192, 255, 98, 98);
    uja_qillqa("R wasitata | Q mistuña", 292, 222, 222, 228, 235);
  } maysatxa ukaxa(pausa) {
    uja_suyu(252, 162, 324, 108, 18, 26, 38);
    uja_qillqa("SAMART'ATA", 342, 192, 248, 236, 132);
    uja_qillqa("P wasitata sarantaya", 298, 222, 220, 228, 235);
  }

  uja_ustaya();
  kuttaya;
}

yatiya chiqa sarantawi = uja_qallta(UJA_ANCHU, UJA_SAYA, "Jamachi Uja");

ukaxa(sarantawi) {
  anatawi_qallta();

  ukhakamaxa(sarantawi && uja_utji()) {
    yatiya jakhüwi k = tecla();

    yatiya chiqa ima_q = (k == 113 || k == 81 || k == 27 || uja_tecla(113) || uja_tecla(81) || uja_tecla(27));
    yatiya chiqa ima_r = (k == 114 || k == 82 || uja_tecla(114) || uja_tecla(82));
    yatiya chiqa ima_w = (k == 119 || k == 87 || k == 1001 || k == 32 || uja_tecla(119) || uja_tecla(87) || uja_tecla(1001) || uja_tecla(32));
    yatiya chiqa ima_p = (k == 112 || k == 80 || uja_tecla(112) || uja_tecla(80));

    ukaxa(ima_q) {
      sarantawi = k'ari;
    }

    ukaxa(ima_r) {
      anatawi_qallta();
    }

    ukaxa(! tukusi) {
      ukaxa(ima_p && pausa_listo) {
        ukaxa(pausa) {
          pausa = k'ari;
        } maysatxa {
          pausa = chiqa;
        }
        pausa_listo = k'ari;
      }
      ukaxa(! ima_p) { pausa_listo = chiqa; }

      ukaxa(! pausa) {
        ukaxa(ima_w && thaqta_listo) {
          chamancha = -3;
          thaqta_listo = k'ari;
        }
      }
      ukaxa(! ima_w) { thaqta_listo = chiqa; }

      yatiya jakhüwi jichha = tiempo_ms();
      ukaxa(! pausa && jichha >= jutiri) {
        chamancha = chamancha + 1;
        ukaxa(chamancha > 3) { chamancha = 3; }
        jamachi_y = jamachi_y + chamancha;
        jarkana_muyu();
        ukaxa(tukuriti()) { tukusi = chiqa; }
        jutiri = jichha + ritmo_jichha();
      }
    }

    dibuja();
    sleep(16);
  }

  uja_tukuya();
}

qillqa("Jallalla!");

samples/games/gui/sudoku_uja.aym.source:
yatiya jakhüwi UJA_ANCHU = 640;
yatiya jakhüwi UJA_SAYA = 560;
yatiya jakhüwi CELDA = 96;
yatiya jakhüwi OX = 128;
yatiya jakhüwi OY = 84;

yatiya jakhüwi tabla = 0;
yatiya jakhüwi tabla_resuelta = 0;
yatiya jakhüwi chinu = 0;
yatiya jakhüwi ajlli_f = 0;
yatiya jakhüwi ajlli_c = 0;
yatiya jakhüwi anatawi_id = 0;
yatiya jakhüwi qallta_ms = 0;
yatiya jakhüwi pacha_tuku = 0;
yatiya chiqa sarawi_listo = chiqa;
yatiya aru yatiyawi = "Qallta";
yatiya chiqa atipi = k'ari;

lurawi fila_machaqa(jakhüwi a, jakhüwi b, jakhüwi c, jakhüwi d): jakhüwi {
  yatiya jakhüwi fila = array(4);
  array_set(fila, 0, a);
  array_set(fila, 1, b);
  array_set(fila, 2, c);
  array_set(fila, 3, d);
  kuttaya fila;
}

lurawi celda_get(jakhüwi tb, jakhüwi f, jakhüwi c): jakhüwi {
  yatiya jakhüwi fila = array_get(tb, f);
  kuttaya array_get(fila, c);
}

lurawi celda_set(jakhüwi tb, jakhüwi f, jakhüwi c, jakhüwi v) {
  yatiya jakhüwi fila = array_get(tb, f);
  array_set(fila, c, v);
  kuttaya;
}

lurawi waliwja(jakhüwi tb, jakhüwi f, jakhüwi c, jakhüwi v): chiqa {
  ukaxa(v < 1 || v > 4) { kuttaya k'ari; }

  kuti(yatiya jakhüwi i = 0; i < 4; i = i + 1) {
    ukaxa(i != c && celda_get(tb, f, i) == v) { kuttaya k'ari; }
    ukaxa(i != f && celda_get(tb, i, c) == v) { kuttaya k'ari; }
  }

  yatiya jakhüwi f0 = (f / 2) * 2;
  yatiya jakhüwi c0 = (c / 2) * 2;
  kuti(yatiya jakhüwi df = 0; df < 2; df = df + 1) {
    kuti(yatiya jakhüwi dc = 0; dc < 2; dc = dc + 1) {
      yatiya jakhüwi ff = f0 + df;
      yatiya jakhüwi cc = c0 + dc;
      ukaxa((ff != f || cc != c) && celda_get(tb, ff, cc) == v) {
        kuttaya k'ari;
      }
    }
  }
  kuttaya chiqa;
}

lurawi phuqhatati(jakhüwi tb): chiqa {
  kuti(yatiya jakhüwi f = 0; f < 4; f = f + 1) {
    kuti(yatiya jakhüwi c = 0; c < 4; c = c + 1) {
      yatiya jakhüwi v = celda_get(tb, f, c);
      ukaxa(v == 0) { kuttaya k'ari; }
      ukaxa(! waliwja(tb, f, c, v)) { kuttaya k'ari; }
    }
  }
  kuttaya chiqa;
}

lurawi cargar_anatawi(jakhüwi id) {
  tabla = array(4);
  tabla_resuelta = array(4);

  ukaxa(id == 0) {
    array_set(tabla, 0, fila_machaqa(1, 0, 0, 4));
    array_set(tabla, 1, fila_machaqa(0, 4, 1, 2));
    array_set(tabla, 2, fila_machaqa(2, 1, 4, 0));
    array_set(tabla, 3, fila_machaqa(4, 0, 2, 1));

    array_set(tabla_resuelta, 0, fila_machaqa(1, 2, 3, 4));
    array_set(tabla_resuelta, 1, fila_machaqa(3, 4, 1, 2));
    array_set(tabla_resuelta, 2, fila_machaqa(2, 1, 4, 3));
    array_set(tabla_resuelta, 3, fila_machaqa(4, 3, 2, 1));
  } maysatxa ukaxa(id == 1) {
    array_set(tabla, 0, fila_machaqa(3, 0, 0, 2));
    array_set(tabla, 1, fila_machaqa(0, 2, 3, 4));
    array_set(tabla, 2, fila_machaqa(4, 3, 2, 0));
    array_set(tabla, 3, fila_machaqa(2, 0, 4, 3));

    array_set(tabla_resuelta, 0, fila_machaqa(3, 4, 1, 2));
    array_set(tabla_resuelta, 1, fila_machaqa(1, 2, 3, 4));
    array_set(tabla_resuelta, 2, fila_machaqa(4, 3, 2, 1));
    array_set(tabla_resuelta, 3, fila_machaqa(2, 1, 4, 3));
  } maysatxa {
    array_set(tabla, 0, fila_machaqa(2, 0, 0, 3));
    array_set(tabla, 1, fila_machaqa(0, 3, 2, 1));
    array_set(tabla, 2, fila_machaqa(1, 2, 3, 0));
    array_set(tabla, 3, fila_machaqa(3, 0, 1, 2));

    array_set(tabla_resuelta, 0, fila_machaqa(2, 1, 4, 3));
    array_set(tabla_resuelta, 1, fila_machaqa(4, 3, 2, 1));
    array_set(tabla_resuelta, 2, fila_machaqa(1, 2, 3, 4));
    array_set(tabla_resuelta, 3, fila_machaqa(3, 4, 1, 2));
  }
  kuttaya;
}

lurawi anatawi_wakicha(jakhüwi id) {
  ukaxa(id < 0) {
    anatawi_id = random(3);
  } maysatxa {
    anatawi_id = id;
  }

  cargar_anatawi(anatawi_id);

  chinu = array(4);
  kuti(yatiya jakhüwi f = 0; f < 4; f = f + 1) {
    yatiya jakhüwi fm = array(4);
    kuti(yatiya jakhüwi c = 0; c < 4; c = c + 1) {
      ukaxa(celda_get(tabla, f, c) == 0) {
        array_set(fm, c, 0);
      } maysatxa {
        array_set(fm, c, 1);
      }
    }
    array_set(chinu, f, fm);
  }

  ajlli_f = 0;
  ajlli_c = 0;
  yatiya aru msj = "Anatawi #" + aru(anatawi_id + 1) + " qallta";
  yatiyawi = msj;
  qallta_ms = tiempo_ms();
  pacha_tuku = 0;
  sarawi_listo = chiqa;
  atipi = k'ari;
  kuttaya;
}

lurawi jani_wali_jakhuwi(): jakhüwi {
  yatiya jakhüwi n = 0;
  kuti(yatiya jakhüwi f = 0; f < 4; f = f + 1) {
    kuti(yatiya jakhüwi c = 0; c < 4; c = c + 1) {
      ukaxa(celda_get(chinu, f, c) == 0) {
        yatiya jakhüwi v = celda_get(tabla, f, c);
        ukaxa(v != 0 && v != celda_get(tabla_resuelta, f, c)) {
          n = n + 1;
        }
      }
    }
  }
  kuttaya n;
}

lurawi puchu_jakhuwi(): jakhüwi {
  yatiya jakhüwi n = 0;
  kuti(yatiya jakhüwi f = 0; f < 4; f = f + 1) {
    kuti(yatiya jakhüwi c = 0; c < 4; c = c + 1) {
      ukaxa(celda_get(tabla, f, c) == 0) { n = n + 1; }
    }
  }
  kuttaya n;
}

lurawi atiptati(): chiqa {
  kuti(yatiya jakhüwi f = 0; f < 4; f = f + 1) {
    kuti(yatiya jakhüwi c = 0; c < 4; c = c + 1) {
      ukaxa(celda_get(tabla, f, c) != celda_get(tabla_resuelta, f, c)) {
        kuttaya k'ari;
      }
    }
  }
  kuttaya chiqa;
}

lurawi pacha_segundos(): jakhüwi {
  ukaxa(atipi) { kuttaya pacha_tuku; }
  kuttaya (tiempo_ms() - qallta_ms) / 1000;
}

lurawi chimpu_mayjtaya(jakhüwi k) {
  yatiya jakhüwi waka = celda_get(chinu, ajlli_f, ajlli_c);
  ukaxa(waka == 1) {
    yatiyawi = "Aka chiqaxa jan mayjtaykanti";
    kuttaya;
  }

  ukaxa(k >= 49 && k <= 52) {
    yatiya jakhüwi v = k - 48;
    ukaxa(waliwja(tabla, ajlli_f, ajlli_c, v)) {
      celda_set(tabla, ajlli_f, ajlli_c, v);
      yatiyawi = "Waliwa";
    } maysatxa {
      yatiyawi = "Jan wali chimpu";
    }
    kuttaya;
  }

  ukaxa(k == 48 || k == 8) {
    celda_set(tabla, ajlli_f, ajlli_c, 0);
    yatiyawi = "Ch'usachata";
  }
  kuttaya;
}

lurawi churapta_pista() {
  yatiya jakhüwi waka = celda_get(chinu, ajlli_f, ajlli_c);
  ukaxa(waka == 1) {
    yatiyawi = "Aka chiqaxa jan mayjtaykanti";
    kuttaya;
  }

  yatiya jakhüwi sasa = celda_get(tabla_resuelta, ajlli_f, ajlli_c);
  ukaxa(celda_get(tabla, ajlli_f, ajlli_c) == sasa) {
    yatiyawi = "Aka chiqaxa walikiwa";
    kuttaya;
  }

  celda_set(tabla, ajlli_f, ajlli_c, sasa);
  yatiyawi = "Pista churata";
  kuttaya;
}

lurawi pinta_celda(jakhüwi f, jakhüwi c) {
  yatiya jakhüwi x = OX + c * CELDA;
  yatiya jakhüwi y = OY + f * CELDA;
  yatiya jakhüwi v = celda_get(tabla, f, c);
  yatiya chiqa fija = (celda_get(chinu, f, c) == 1);
  yatiya chiqa ajlli = (f == ajlli_f && c == ajlli_c);
  yatiya chiqa janiwa = k'ari;
  ukaxa(! fija && v != 0 && v != celda_get(tabla_resuelta, f, c)) {
    janiwa = chiqa;
  }

  ukaxa(ajlli) {
    uja_suyu(x + 1, y + 1, CELDA - 2, CELDA - 2, 54, 80, 140);
  } maysatxa ukaxa(janiwa) {
    uja_suyu(x + 1, y + 1, CELDA - 2, CELDA - 2, 86, 36, 40);
  } maysatxa ukaxa(fija) {
    uja_suyu(x + 1, y + 1, CELDA - 2, CELDA - 2, 36, 50, 72);
  } maysatxa {
    uja_suyu(x + 1, y + 1, CELDA - 2, CELDA - 2, 24, 30, 44);
  }

  ukaxa(v != 0) {
    yatiya aru s = aru(v);
    ukaxa(fija) {
      uja_qillqa(s, x + 38, y + 34, 248, 225, 138);
    } maysatxa ukaxa(janiwa) {
      uja_qillqa(s, x + 38, y + 34, 255, 170, 170);
    } maysatxa {
      uja_qillqa(s, x + 38, y + 34, 220, 240, 255);
    }
  }
  kuttaya;
}

lurawi dibuja() {
  uja_pichha(14, 17, 24);

  uja_qillqa("Sudoku 4x4 Uja", 16, 14, 240, 240, 240);
  uja_qillqa("A/D/W/S jan ukaxa flecha | 1..4 uchanta | 0 pichha | H pista | R wasitata | N machaqa | Q mistuña", 16, 40, 178, 196, 216);

  uja_suyu(OX - 4, OY - 4, CELDA * 4 + 8, CELDA * 4 + 8, 188, 198, 210);

  kuti(yatiya jakhüwi i = 1; i < 4; i = i + 1) {
    yatiya jakhüwi px = OX + i * CELDA;
    yatiya jakhüwi py = OY + i * CELDA;

    ukaxa(i == 2) {
      uja_suyu(px - 2, OY, 4, CELDA * 4, 188, 198, 210);
      uja_suyu(OX, py - 2, CELDA * 4, 4, 188, 198, 210);
    } maysatxa {
      uja_suyu(px - 1, OY, 2, CELDA * 4, 108, 120, 140);
      uja_suyu(OX, py - 1, CELDA * 4, 2, 108, 120, 140);
    }
  }

  kuti(yatiya jakhüwi f = 0; f < 4; f = f + 1) {
    kuti(yatiya jakhüwi c = 0; c < 4; c = c + 1) {
      pinta_celda(f, c);
    }
  }

  yatiya jakhüwi panel_x = OX + CELDA * 4 + 18;
  yatiya jakhüwi panel_y = OY + 18;
  yatiya jakhüwi panel_w = 102;
  yatiya jakhüwi panel_h = 224;
  uja_suyu(panel_x - 3, panel_y - 24, panel_w + 6, panel_h + 30, 186, 198, 210);
  uja_suyu(panel_x, panel_y, panel_w, panel_h, 22, 30, 42);

  uja_qillqa("Panel", panel_x + 24, panel_y - 16, 235, 235, 245);
  uja_qillqa("Anatawi: " + aru(anatawi_id + 1), panel_x + 8, panel_y + 12, 216, 230, 248);
  uja_qillqa("Puchu: " + aru(puchu_jakhuwi()), panel_x + 8, panel_y + 42, 216, 230, 248);
  uja_qillqa("Pantja: " + aru(jani_wali_jakhuwi()), panel_x + 8, panel_y + 72, 255, 184, 184);
  uja_qillqa("Pacha(s): " + aru(pacha_segundos()), panel_x + 8, panel_y + 102, 190, 225, 190);
  uja_qillqa("H: pista", panel_x + 8, panel_y + 146, 220, 220, 220);
  uja_qillqa("N: machaqa", panel_x + 8, panel_y + 170, 220, 220, 220);

  yatiya aru msj = "Yatiyawi: " + yatiyawi;
  uja_qillqa(msj, 16, UJA_SAYA - 64, 230, 230, 230);

  ukaxa(atipi) {
    uja_suyu(138, 478, 364, 56, 20, 34, 58);
    uja_qillqa("Atiptawa! R wasitata | Q mistuña", 156, 497, 170, 236, 170);
  }

  uja_ustaya();
  kuttaya;
}

yatiya chiqa sarantawi = uja_qallta(UJA_ANCHU, UJA_SAYA, "Sudoku 4x4 Uja");

ukaxa(sarantawi) {
  anatawi_wakicha(-1);

  ukhakamaxa(sarantawi && uja_utji()) {
    yatiya jakhüwi k = tecla();

    yatiya chiqa ima_a = (k == 97 || k == 65 || k == 1003 || uja_tecla(97) || uja_tecla(65) || uja_tecla(1003));
    yatiya chiqa ima_d = (k == 100 || k == 68 || k == 1004 || uja_tecla(100) || uja_tecla(68) || uja_tecla(1004));
    yatiya chiqa ima_w = (k == 119 || k == 87 || k == 1001 || uja_tecla(119) || uja_tecla(87) || uja_tecla(1001));
    yatiya chiqa ima_s = (k == 115 || k == 83 || k == 1002 || uja_tecla(115) || uja_tecla(83) || uja_tecla(1002));
    yatiya chiqa ima_q = (k == 113 || k == 81 || k == 27 || uja_tecla(113) || uja_tecla(81) || uja_tecla(27));
    yatiya chiqa ima_r = (k == 114 || k == 82 || uja_tecla(114) || uja_tecla(82));
    yatiya chiqa ima_h = (k == 104 || k == 72 || uja_tecla(104) || uja_tecla(72));
    yatiya chiqa ima_n = (k == 110 || k == 78 || uja_tecla(110) || uja_tecla(78));

    ukaxa(ima_q) {
      sarantawi = k'ari;
    }

    ukaxa(ima_r) {
      anatawi_wakicha(anatawi_id);
    }

    ukaxa(ima_n) {
      anatawi_wakicha(-1);
    }

    ukaxa(! atipi) {
      yatiya chiqa ima_sarawi = (ima_a || ima_d || ima_w || ima_s);
      ukaxa(ima_sarawi && sarawi_listo) {
        ukaxa(ima_a && ajlli_c > 0) { ajlli_c = ajlli_c - 1; }
        ukaxa(ima_d && ajlli_c < 3) { ajlli_c = ajlli_c + 1; }
        ukaxa(ima_w && ajlli_f > 0) { ajlli_f = ajlli_f - 1; }
        ukaxa(ima_s && ajlli_f < 3) { ajlli_f = ajlli_f + 1; }
        sarawi_listo = k'ari;
      }
      ukaxa(! ima_sarawi) { sarawi_listo = chiqa; }

      ukaxa((k >= 48 && k <= 52) || k == 8) {
        chimpu_mayjtaya(k);
      }

      ukaxa(ima_h) {
        churapta_pista();
      }

      ukaxa(atiptati()) {
        atipi = chiqa;
        pacha_tuku = (tiempo_ms() - qallta_ms) / 1000;
        yatiyawi = "Atiptawa";
      }
    }

    dibuja();
    sleep(16);
  }

  uja_tukuya();
}

qillqa("Jallalla!");

